with parsed as (select id, customer_id, created_at, coupon_codes, items, attributes['gift'] as gift, aggregate(items, 0D, (acc, i) -> acc + i.qty * i.price, acc -> round(acc, 2)) as basket_amount, forall(items, i -> i.qty <= 5) as all_small_qty from carts where customer_id is not null) select id, customer_id, basket_amount, all_small_qty, lead(basket_amount) over w_ordered as next_basket_amount, lag(basket_amount) over w_ordered as prev_basket_amount, row_number() over w_ordered as event_seq from parsed window w_ordered as (partition by customer_id order by created_at asc, id asc)
